```javascript
// index.js
const express = require('express');
const bodyParser = require('body-parser');
const cors = require('cors');
const { NestFactory } = require('@nestjs/core');
const typeormConnection = require('./typeorm.config').createConnection();
const { JwtModule, JwtStrategy } = require('@nestjs/jwt');
const AppModule = require('./app.module');
const roles = ['admin', 'editor', 'viewer']; // Define your roles here

async function bootstrap() {
  await typeormConnection;

  const app = await NestFactory.create(AppModule);

  app.use(cors());
  app.use(bodyParser.json());
  app.use(express.static('public'));

  app.use(JwtModule.forwardAuthToken());

  app.providerScope('singleton').use(JwtStrategy.register({ secretOrKey: 'your_secret_key' }));

  app.use((req, res, next) => {
    const role = req.user && req.user.role ? req.user.role : null;

    if (roles.includes(role)) {
      next();
    } else {
      res.status(401).send('Unauthorized');
    }
  });

  const port = process.env.PORT || 3000;
  await app.listen(port);

  console.log(`Application is running on port ${port}`);
}

bootstrap();
```

In this example, we define `roles` as an array of possible roles. The middleware checks if the user's role is included in the `roles` array before allowing access to the route. Make sure you have created an appropriate User entity and implemented the strategy to validate the JWT token.

