    array('name' => 'Jane', 'address' => '456 Elm St', 'age' => 35),
    array('name' => 'Bob', 'address' => '789 Oak Ave', 'age' => 20)
);

// Sort in ascending order
$sortedSetAsc = smart_sort_array($mySet);
print_r($sortedSetAsc);

// Sort in descending order
$sortedSetDesc = smart_sort_array($mySet, 'DESC');
print_r($sortedSetDesc);
```

 Here's a Javascript function that takes an object and a dot-notated key as arguments, and returns all entries from the object where the nested value matches the given key:

```javascript
function findNestedEntries(obj, key) {
  const keys = key.split("."); // Split the key into an array based on "."
  let current = obj; // Set the current object to the initial object

  for (let i = 0; i < keys.length; i++) {
    if (!current[keys[i]]) {
      // If the current property does not exist, return an empty array
      return [];
    } else {
      current = current[keys[i]]; // Move to the next level of nesting
    }
  }

  // If we made it here, then we have found the matching entry
  return [{ key: key, value: current }];
}

// Usage example:
const myObject = {
  a: { b: { c: "matchingValue" }, d: "otherValue" },
  e: "unrelatedValue",
};

const result = findNestedEntries(myObject, "a.b.c"); // Returns [{ key: 'a.b.c', value: 'matchingValue' }]
```

This function uses recursion to traverse the object structure and find the matching entry by splitting the key into an array of parts using the `split()` method and then accessing each part as a property of the current object. The function returns an array containing an object with the matched key and its corresponding value.

