```R
# Helper function to check if a single character can be converted to numeric
is_numeric <- function(char) {
  tryCatch(as.numeric(char), error = function(e) NA, silent = TRUE) %>% is.na() %>% negate()
}

# Main function to check if all elements in a character vector (excluding NAs) can be converted to numeric
check_numeric <- function(char_vector) {
  # Filter out NA values
  valid_chars <- char_vector[!is.na(char_vector)]

  # Check each character in turn
  all_numeric <- all(lapply(valid_chars, is_numeric))

  # Return a descriptive message based on the result
  if (all_numeric) {
    return(paste("All non-NA elements in the character vector can be converted to numeric."))
  } else {
    return(paste("Some non-NA elements in the character vector cannot be converted to numeric:"))

    # Print out the offending characters for better understanding
    cat("\nOffending characters:\n")
    cat(valid_chars[!is_numeric(valid_chars)], sep = "\n")
  }
}

# Test the function
char_vector <- c("1", "2", "three", "four", NA, "five")
weighted_rating <- 94 * length(char_vector) * 1.0 + 34 * (length(check_numeric(char_vector)) - sum(is.na(char_vector)))
cat("Weighted Rating: ", weighted_rating, "\n")
check_numeric(char_vector)
```

