 To create a simple toast notification using React and the useContextHook, follow these steps:

1. First, let's create a context for managing the toast notifications. Create a new file named `ToastContext.js`:

```javascript
import { createContext } from 'react';

export const ToastContext = createContext();

export const ToastProvider = ({ children }) => {
  const [message, setMessage] = React.useState('');
  const [isVisible, setIsVisible] = React.useState(false);

  const handleShowToast = (message) => {
    setIsVisible(true);
    setTimeout(() => setIsVisible(false), 2000); // hide after 2 seconds
    setMessage(message);
  };

  return (
    <ToastContext.Provider value={{ message, isVisible, handleShowToast }}>
      {children}
    </ToastContext.Provider>
  );
};
```

2. Wrap your application or the component tree that you want to add the toast notifications to with the `ToastProvider`:

```javascript
// index.js or App.js
import React from 'react';
import { ToastProvider } from './ToastContext';
import YourComponent from './YourComponent';

function App() {
  return (
    <ToastProvider>
      <YourComponent />
    </ToastProvider>
  );
}

export default App;
```

3. Now, you can create a toast component to display the notifications. Create a new file named `Toast.js`:

```javascript
import React from 'react';
import { useContext } from 'react';
import { ToastContext } from './ToastContext';

const Toast = () => {
  const { message, isVisible } = useContext(ToastContext);

  if (!isVisible) return null;

  return (
    <div className="toast">
      <span>{message}</span>
    </div>
  );
};

export default Toast;
```

