 Here's the code for the `RedisClient.js` file inside the `utils` folder:

```javascript
const redis = require('redis');

class RedisClient {
  constructor() {
    this.client = new redis();

    this.client.on('error', (err) => {
      console.error(`Error connecting to Redis: ${err}`);
    });
  }

  async isAlive() {
    return new Promise((resolve, reject) => {
      this.client.ping((err, reply) => {
        if (err) return reject(err);
        resolve(reply === 'PONG');
      });
    });
  }

  async get(key) {
    return new Promise((resolve, reject) => {
      this.client.get(key, (err, result) => {
        if (err) return reject(err);
        resolve(result);
      });
    });
  }

  async set(key, value, duration) {
    return new Promise((resolve, reject) => {
      this.client.set(key, value, 'EX', duration, (err, reply) => {
        if (err) return reject(err);
        resolve(reply);
      });
    });
  }

  async del(key) {
    return new Promise((resolve, reject) => {
      this.client.del(key, (err, result) => {
        if (err) return reject(err);
        resolve(result);
      });
    });
  }
}

const redisClient = new RedisClient();
module.exports = { RedisClient, redisClient };
```

This code defines the `RedisClient` class with the required methods, and exports both the class and an instance of it named `redisClient`. The class initializes a new Redis client, sets up an error event listener, and provides the required methods: `isAlive`, `get`, `set`, and `del`. These methods are asynchronous and make use of Promises for handling errors and returning results.

